const body = $json.body || $json;
const payload = body.payload || body;
const tenant = payload.tenant || {};
const invoice = payload.invoice || {};
const rule = payload.rule || {};
function digits(v){ return String(v || '').replace(/\D/g, ''); }
const phone = digits(tenant.phone || payload.phone || '');
const paymentUrl = invoice.payment_url || payload.payment_url || '';
const message = payload.message || `Olá, ${tenant.name || 'cliente'}. Existe uma cobrança em aberto no RS Connect. ${paymentUrl ? 'Link: ' + paymentUrl : ''}`;
return [{ json: {
  event: body.event || payload.event || rule.event || 'billing.reminder',
  tenant_id: body.tenant_id || payload.tenant_id || tenant.id,
  flow_id: body.flow_id || payload.flow_id || null,
  callback_url: body.callback?.url || payload.callback?.url || body.callback_url || payload.callback_url || '',
  callback_token: body.callback?.token || payload.callback?.token || body.callback_token || payload.callback_token || '',
  company_name: tenant.name || '', email: tenant.email || '', phone,
  invoice_number: invoice.number || '', amount: invoice.amount || 0, due_date: invoice.due_date || '', payment_url: paymentUrl, message
} }];

const source = $('Normalizar cobrança').first().json;
const callbackToken = String(source.callback_token || '');
if (!callbackToken) throw new Error('callback_token não configurado.');
const callbackBody = {
  tenant_id: source.tenant_id,
  flow_id: source.flow_id,
  event: source.event,
  status: 'success',
  external_id: source.invoice_number,
  message: 'Mensagem de cobrança disparada pelo n8n',
  idempotency_key: `${source.event || 'billing'}:${source.invoice_number || ''}:success`,
};
const rawBody = JSON.stringify(callbackBody);
const callbackTimestamp = Math.floor(Date.now() / 1000).toString();
const encoder = new TextEncoder();
const key = await crypto.subtle.importKey(
  'raw', encoder.encode(callbackToken),
  { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']
);
const signature = await crypto.subtle.sign(
  'HMAC', key, encoder.encode(`${callbackTimestamp}.${rawBody}`)
);
const callbackSignature = Array.from(new Uint8Array(signature))
  .map((byte) => byte.toString(16).padStart(2, '0')).join('');
return [{ json: { callback_body: callbackBody, callback_token: callbackToken, callback_timestamp: callbackTimestamp, callback_signature: callbackSignature } }];
